function persist(){
  const data={...state,completed:[...state.completed],guidedDone:[...state.guidedDone],guidedTried:[...state.guidedTried],ladderDone:[...state.ladderDone],examTimer:null,totalTimer:null};
  try{localStorage.setItem(STORAGE,JSON.stringify(data));}catch(e){/* Progress persistence is optional; lesson functionality continues without it. */}
}
function restore(){
  try{const raw=JSON.parse(localStorage.getItem(STORAGE)||'null');if(!raw)return;
    state.completed=new Set(raw.completed||[]);state.fr=!!raw.fr;state.solo=!!raw.solo;state.currentGuided=Math.min(raw.currentGuided||0,guided.length-1);
    state.guidedDone=new Set(raw.guidedDone||[]);state.guidedFirst=raw.guidedFirst||0;state.guidedTried=new Set(raw.guidedTried||[]);state.guidedMistakes=raw.guidedMistakes||{};state.guidedPlays=raw.guidedPlays||{};
    state.ladderDone=new Set(raw.ladderDone||[]);state.examScore=raw.examScore??null;state.examDone=!!raw.examDone;state.examAnswers=raw.examAnswers||[];state.examPlays=raw.examPlays||{};state.accent=raw.accent||'GB';
  }catch(e){console.warn('Progress restore failed',e);}
}

function renderListeningMap(){
  $('#listeningMap').innerHTML=listeningMap.map(([tag,title,desc])=>`<article><span>${esc(tag)}</span><h3>${esc(title)}</h3><p>${esc(desc)}</p></article>`).join('');
}
function populateFilters(){
  const types=[...new Set(audioLibrary.map(x=>x.type))].sort();
  $('#typeFilter').innerHTML='<option value="All">All situations</option>'+types.map(x=>`<option>${esc(x)}</option>`).join('');
  $('#accentFilter').value=state.accent;
}
function filteredAudio(){
  const level=$('#levelFilter').value,type=$('#typeFilter').value,q=norm($('#audioSearch').value);
  return audioLibrary.filter(x=>(level==='All'||x.level===level)&&(type==='All'||x.type===type)&&(!q||norm(`${x.title} ${x.purpose} ${x.signals} ${x.transcript}`).includes(q)));
}
function renderAudioLibrary(items=filteredAudio()){
  $('#audioCount').textContent=items.length;
  $('#audioLibrary').innerHTML=items.map((x,i)=>`<article class="audio-card">
    <div class="audio-card-top"><span>${esc(x.level)} · ${esc(x.type)}</span><span>${esc(x.signals)}</span></div>
    <h3>${esc(x.title)}</h3><p><b>Listening target:</b> ${esc(x.purpose)}</p>
    <div class="audio-actions"><button class="audio-btn" data-lib-play="${i}" type="button">▶ Play manually</button><button class="transcript-btn" data-lib-transcript="${i}" type="button">Transcript</button></div>
    <div class="transcript" id="libTranscript${i}"><b>Transcript</b><br>${esc(x.transcript)}<div class="fr-inline">FR: ${esc(x.fr)}</div></div>
  </article>`).join('') || '<div class="official-note"><div class="official-icon">i</div><div><b>No matches</b><p>Change the filters or search term.</p></div></div>';
  $$('[data-lib-play]').forEach(btn=>btn.addEventListener('click',()=>{const x=items[Number(btn.dataset.libPlay)];playSegments(x.segments,state.accent,btn);}));
  $$('[data-lib-transcript]').forEach(btn=>btn.addEventListener('click',()=>{const el=$(`#libTranscript${btn.dataset.libTranscript}`);el.classList.toggle('open');btn.textContent=el.classList.contains('open')?'Hide transcript':'Transcript';}));
}

function langForAccent(accent){return accent==='US'?'en-US':accent==='AU'?'en-AU':'en-GB';}
function voiceFor(lang,alt=0){
  const voices=speechSynthesis.getVoices();
  const exact=voices.filter(v=>v.lang&&v.lang.toLowerCase()===lang.toLowerCase());
  const family=voices.filter(v=>v.lang&&v.lang.toLowerCase().startsWith('en'));
  const pool=exact.length?exact:family;return pool.length?pool[alt%pool.length]:null;
}
function stopSpeech(){if('speechSynthesis'in window)speechSynthesis.cancel();$$('.audio-btn.playing,.play-audio.playing').forEach(x=>x.classList.remove('playing'));}
function playSegments(segments,accent='GB',button=null,onEnd=null){
  if(!('speechSynthesis'in window)){alert('Speech playback is not supported in this browser.');return;}
  stopSpeech();const lang=langForAccent(accent);let i=0;if(button)button.classList.add('playing');
  const next=()=>{if(i>=segments.length){if(button)button.classList.remove('playing');onEnd?.();return;}const u=new SpeechSynthesisUtterance(segments[i]);u.lang=lang;u.rate=0.92;const v=voiceFor(lang,i);if(v)u.voice=v;u.onend=()=>{i++;setTimeout(next,180)};u.onerror=()=>{i++;next()};speechSynthesis.speak(u);};next();
}

function setFrench(on){state.fr=on;document.body.classList.toggle('fr-hidden',!on);$('#toggleFrench').setAttribute('aria-pressed',String(on));$('#toggleFrench').classList.toggle('active',on);persist();}
function setMode(solo){state.solo=solo;$('#guidedMode').classList.toggle('active',!solo);$('#soloMode').classList.toggle('active',solo);renderGuided();persist();}
function typeLabel(t){return t==='mcq'?'SINGLE-ANSWER MULTIPLE CHOICE':t==='dropdown'?'GAP-FILL · DROP-DOWN':'GAP-FILL · TYPED ANSWER';}
function playCount(kind,i){return kind==='guided'?(state.guidedPlays[i]||0):(state.examPlays[i]||0);}
function addPlay(kind,i){if(kind==='guided')state.guidedPlays[i]=(state.guidedPlays[i]||0)+1;else state.examPlays[i]=(state.examPlays[i]||0)+1;persist();}

function answerMarkup(q,where,mode){
  if(q.type==='mcq')where.insertAdjacentHTML('beforeend',`<div class="answer-grid">${q.options.map((o,i)=>`<button class="answer-option" data-choice="${i}" type="button">${esc(o)}</button>`).join('')}</div>`);
  if(q.type==='dropdown')where.insertAdjacentHTML('beforeend',`<label class="select-wrap"><select class="select-answer"><option value="">Choose…</option>${q.options.map(o=>`<option>${esc(o)}</option>`).join('')}</select></label>`);
  if(q.type==='text')where.insertAdjacentHTML('beforeend',`<label class="typed-wrap"><input class="typed-answer" autocomplete="off" placeholder="Type your answer" /></label>`);
  $$('.answer-option',where).forEach(b=>b.addEventListener('click',()=>{$$('.answer-option',where).forEach(x=>x.classList.remove('selected'));b.classList.add('selected');where.dataset.choice=b.dataset.choice;if(mode==='guided'&&!state.solo)setTimeout(validateGuided,160);}));
  $('.select-answer',where)?.addEventListener('change',e=>{if(mode==='guided'&&!state.solo&&e.target.value)setTimeout(validateGuided,160);});
  $('.typed-answer',where)?.addEventListener('keydown',e=>{if(e.key==='Enter'&&mode==='guided')validateGuided();});
}
function readAnswer(q,where){if(q.type==='mcq'){const selected=$('.answer-option.selected',where);return selected?Number(selected.dataset.choice):null;}if(q.type==='dropdown')return $('.select-answer',where)?.value||'';return $('.typed-answer',where)?.value||'';}
function isCorrect(q,a){if(q.type==='mcq')return a===q.answer;if(q.type==='dropdown')return norm(a)===norm(q.answer);return (q.answers||[]).some(x=>norm(a)===norm(x));}
function hasAnswer(q,a){return q.type==='mcq'?a!==null:!!String(a||'').trim();}
function answerDisplay(q){return q.type==='mcq'?q.options[q.answer]:q.type==='dropdown'?q.answer:q.answers[0];}
function lockInputs(where){$$('button.answer-option,select,input',where).forEach(x=>x.disabled=true);}

function renderAudioQuestion(q,where,kind,index){
  const plays=playCount(kind,index),limit=2;
  where.innerHTML=`<div class="audio-question-card"><div class="audio-question-head"><div><b>${esc(q.title||'Listen carefully')}</b><div class="accent-note">Manual audio · ${state.accent==='GB'?'UK':state.accent==='US'?'US':'Australian'} voice when available</div></div><span class="play-limit" id="playLimit">${plays} / ${limit} plays</span></div>
    <div class="audio-player-row"><button class="play-audio" id="playAudio" type="button" ${plays>=limit?'disabled':''}>▶ PLAY AUDIO</button>${kind==='guided'?`<button class="transcript-btn" id="toggleTranscript" type="button" ${state.solo||plays<1?'disabled':''}>Transcript</button>`:''}</div>
    ${kind==='guided'?`<div class="hidden-transcript" id="guidedTranscript"><b>Transcript</b><br>${esc(q.transcript)}<div class="fr-inline">FR Coach: ${esc(q.frTip||'')}</div></div>`:''}
  </div><p class="instruction"><b>${esc(q.prompt)}</b></p><div id="answerArea"></div>`;
  $('#playAudio',where).addEventListener('click',()=>{
    const current=playCount(kind,index);if(current>=limit)return;addPlay(kind,index);const btn=$('#playAudio',where),counter=$('#playLimit',where);counter.textContent=`${current+1} / ${limit} plays`;if(current+1>=limit)btn.disabled=true;
    playSegments(q.segments,state.accent,btn);
    if(kind==='guided'&&!state.solo){const tr=$('#toggleTranscript',where);if(tr)tr.disabled=false;}
  });
  if(kind==='guided')$('#toggleTranscript',where)?.addEventListener('click',()=>{if(state.solo)return;const t=$('#guidedTranscript',where);t.classList.toggle('open');$('#toggleTranscript',where).textContent=t.classList.contains('open')?'Hide transcript':'Transcript';});
  answerMarkup(q,$('#answerArea',where),kind);
}

function renderGuided(){
  stopSpeech();const i=state.currentGuided,q=guided[i];
  $('#guidedStage').innerHTML=`<div class="exercise-head"><div class="exercise-meta"><span>GUIDED LISTENING · ${esc(q.level)} · ${esc(q.focus)}</span><b>${i+1} of ${guided.length}</b></div><div class="guided-dots">${guided.map((_,j)=>`<i class="${state.guidedDone.has(j)?'done':j===i?'current':''}"></i>`).join('')}</div></div>
  <div class="exercise-main">${state.solo?'<div class="solo-note"><b>Try Alone:</b> transcript, hints and models are hidden. You still have two listens.</div>':''}<span class="exercise-type">${typeLabel(q.type)}</span><h3>${esc(q.title)}</h3><p class="instruction">Read the question first. Then use L.I.S.T.E.N.</p><div id="guidedQuestion"></div><div id="guidedFeedback"></div>
  <div class="exercise-actions"><button class="button ghost small hint-action" id="showHint" type="button" ${state.solo?'disabled':''}>Hint</button><button class="button ghost small model-action" id="showModel" type="button" ${state.solo?'disabled':''}>Model thinking</button><button class="button ghost small" id="checkAnswer" type="button">Check answer</button>${i>0?'<button class="button ghost small" id="prevGuided" type="button">← Previous</button>':''}<button class="button primary small next-btn" id="nextGuided" type="button">${i===guided.length-1?'Finish lab':'Next →'}</button></div></div>`;
  renderAudioQuestion(q,$('#guidedQuestion'),'guided',i);
  $('#showHint').addEventListener('click',()=>showSupport('hint',q));$('#showModel').addEventListener('click',()=>showSupport('model',q));$('#checkAnswer').addEventListener('click',validateGuided);
  $('#nextGuided').addEventListener('click',()=>{stopSpeech();if(i<guided.length-1){state.currentGuided++;persist();renderGuided();}else{state.completed.add(4);persist();updateProgress();document.querySelector('#ladderWrap').scrollIntoView({behavior:'smooth',block:'start'});}});
  $('#prevGuided')?.addEventListener('click',()=>{stopSpeech();state.currentGuided--;persist();renderGuided();});
}
function showSupport(kind,q){if(state.solo)return;const f=$('#guidedFeedback');if(kind==='hint')f.innerHTML=`<div class="hint-box"><b>Hint</b><br>${esc(q.hint)}<div class="fr-inline">FR: ${esc(q.frTip||'')}</div></div>`;if(kind==='model')f.innerHTML=`<div class="model-box"><b>Model route</b><br>${esc(q.model)}<hr><b>Stronger-listener habit</b><br>${esc(q.modelPlus)}</div>`;}
function validateGuided(){
  const i=state.currentGuided,q=guided[i],where=$('#guidedQuestion'),a=readAnswer(q,where);if(!hasAnswer(q,a))return;
  const ok=isCorrect(q,a),first=!state.guidedTried.has(i);state.guidedTried.add(i);if(first&&ok)state.guidedFirst++;if(first&&!ok)state.guidedMistakes[q.focus]=(state.guidedMistakes[q.focus]||0)+1;if(ok)state.guidedDone.add(i);
  const f=$('#guidedFeedback');f.innerHTML=`<div class="feedback-box ${ok?'good':'bad'}"><b>${ok?'✓ Correct':'✗ Not yet'}</b><br>${esc(q.why)}${ok?`<br><b>Correct answer:</b> ${esc(answerDisplay(q))}`:`<br><b>Try again.</b> ${esc(q.hint)}`}<div class="fr-inline">FR Coach: ${esc(q.frTip||'')}</div></div>`;
  if(q.type==='mcq'){$$('.answer-option',where).forEach((b,j)=>{b.classList.toggle('correct',j===q.answer);if(b.classList.contains('selected')&&j!==q.answer)b.classList.add('wrong');});}
  if(ok){lockInputs(where);persist();updateResults();updateProgress();}
}

function renderLadder(){
  $('#ladder').innerHTML=ladderItems.map((x,i)=>`<article class="ladder-card"><div class="ladder-level"><b>${esc(x.level)}</b><span>${esc(x.skill)}</span></div><div class="ladder-audio"><button class="audio-btn" data-ladder-play="${i}" type="button">▶ Play</button></div><h3>${esc(x.q)}</h3><div class="ladder-options">${x.options.map((o,j)=>`<button type="button" data-ladder="${i}" data-choice="${j}">${esc(o)}</button>`).join('')}</div><div class="ladder-explain" id="ladderExplain${i}"></div></article>`).join('');
  $$('[data-ladder-play]').forEach(b=>b.addEventListener('click',()=>playSegments(ladderItems[Number(b.dataset.ladderPlay)].segments,state.accent,b)));
  $$('[data-ladder]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.ladder),j=Number(b.dataset.choice),x=ladderItems[i],wrap=b.closest('.ladder-card');$$('[data-ladder]',wrap).forEach(btn=>{btn.disabled=true;const k=Number(btn.dataset.choice);btn.classList.toggle('right',k===x.answer);if(k===j&&k!==x.answer)btn.classList.add('wrong');});$(`#ladderExplain${i}`).textContent=x.why;state.ladderDone.add(i);persist();updateProgress();}));
}

function setupExamDots(){$('#examDots').innerHTML=exam.map(()=>'<i></i>').join('');}
function markExamDot(i,status='active'){$$('#examDots i').forEach((d,j)=>{d.classList.remove('active','answered');if(j===i)d.classList.add(status);else if(state.examAnswers[j])d.classList.add('answered');});}
function formatTime(s){s=Math.max(0,Math.ceil(s));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function updateTimerBar(max){const pct=Math.max(0,state.questionLeft/max*100),bar=$('#examTimerBar');bar.style.width=`${pct}%`;bar.style.background=pct>50?'var(--green)':pct>25?'var(--yellow)':'var(--red)';}
function startExam(){
  stopSpeech();clearInterval(state.examTimer);clearInterval(state.totalTimer);state.examIndex=0;state.examAnswers=[];state.examScore=null;state.examDone=false;state.examPlays={};state.totalLeft=480;state.transitioning=false;persist();
  $('#examTotalTime').textContent=formatTime(state.totalLeft);state.totalTimer=setInterval(()=>{state.totalLeft--;$('#examTotalTime').textContent=formatTime(state.totalLeft);if(state.totalLeft<=0){clearInterval(state.totalTimer);finishExam(true);}},1000);renderExamQuestion();
}
function renderExamQuestion(){
  stopSpeech();clearInterval(state.examTimer);state.transitioning=false;const i=state.examIndex,q=exam[i];if(!q)return finishExam();
  $('#examCounter').textContent=`Question ${i+1} / ${exam.length}`;$('#examQuestionLabel').textContent=`LISTENING · ${q.focus.toUpperCase()}`;markExamDot(i,'active');state.questionLeft=q.time;$('#examQuestionTime').textContent=`${state.questionLeft}s`;updateTimerBar(q.time);
  $('#examContent').innerHTML=`<div class="exam-question"><small>${typeLabel(q.type)}</small><h3>Read first. Listen with purpose.</h3><div id="examQuestion"></div><div class="exercise-actions"><button class="button primary" id="validateExam" type="button">VALIDATE</button></div><div id="examTransition"></div></div>`;
  renderAudioQuestion(q,$('#examQuestion'),'exam',i);$('#validateExam').addEventListener('click',()=>submitExam(false));state.examTimer=setInterval(()=>{state.questionLeft--;$('#examQuestionTime').textContent=`${Math.max(0,state.questionLeft)}s`;updateTimerBar(q.time);if(state.questionLeft<=0){clearInterval(state.examTimer);submitExam(true);}},1000);
}
function submitExam(timeout=false){
  if(state.transitioning)return;state.transitioning=true;stopSpeech();clearInterval(state.examTimer);const i=state.examIndex,q=exam[i],where=$('#examQuestion'),a=timeout?null:readAnswer(q,where);const ok=!timeout&&hasAnswer(q,a)&&isCorrect(q,a);state.examAnswers[i]={ok,answer:a,focus:q.focus,plays:state.examPlays[i]||0};lockInputs(where);$('#validateExam').disabled=true;markExamDot(i,'answered');persist();
  let c=3;$('#examTransition').innerHTML=`<div class="model-box">${timeout?'Time is up.':'Answer recorded.'} Next question in <b id="count3">${c}</b>…</div>`;const t=setInterval(()=>{c--;const n=$('#count3');if(n)n.textContent=c;if(c<=0){clearInterval(t);state.examIndex++;if(state.examIndex>=exam.length)finishExam();else renderExamQuestion();}},1000);
}
function finishExam(totalTimeout=false){
  if(state.examDone)return;stopSpeech();clearInterval(state.examTimer);clearInterval(state.totalTimer);state.examDone=true;if(totalTimeout){for(let i=state.examAnswers.length;i<exam.length;i++)state.examAnswers[i]={ok:false,answer:null,focus:exam[i].focus,plays:state.examPlays[i]||0};}
  state.examScore=state.examAnswers.filter(x=>x&&x.ok).length;state.completed.add(5);persist();updateProgress();updateResults();$('#examCounter').textContent='Complete';$('#examQuestionTime').textContent='--';$('#examTimerBar').style.width='100%';$('#examTimerBar').style.background='var(--navy)';
  $('#examContent').innerHTML=`<div class="exam-start-card"><div class="ready-ring">${state.examScore}</div><h3>${state.examScore} / 10</h3><p>${scoreMessage(state.examScore)}</p><div class="result-review">${exam.map((q,i)=>{const r=state.examAnswers[i]||{ok:false,answer:null,plays:0};return `<details><summary><span class="${r.ok?'ok':'no'}">${r.ok?'✓':'✗'}</span> Q${i+1} · ${esc(q.focus)} · ${r.plays}/2 plays</summary><p><b>Correct answer:</b> ${esc(answerDisplay(q))}<br><b>Why:</b> ${esc(q.why)}</p><div class="exam-review-audio"><b>Transcript unlocked</b><br>${esc(q.transcript)}<br><button class="audio-btn review-play" data-review="${i}" type="button">▶ Replay for review</button></div></details>`;}).join('')}</div><button class="button ghost" id="retryExam" type="button">Retry mini-test</button></div>`;
  $$('.review-play').forEach(b=>b.addEventListener('click',()=>playSegments(exam[Number(b.dataset.review)].segments,state.accent,b)));$('#retryExam').addEventListener('click',startExam);document.querySelector('#resultsPanel').scrollIntoView({behavior:'smooth',block:'start'});
}
function scoreMessage(s){if(s>=9)return 'Excellent listening control. Keep the same two-listen discipline with longer, faster extracts.';if(s>=7)return 'Strong result. Review the few listening targets that caused hesitation.';if(s>=5)return 'Good foundation. Use listen one for meaning and listen two only for missing evidence.';return 'Return to L.I.S.T.E.N. and the guided lab before repeating the timed test.';}

function updateProgress(){
  const base=[1,2,3].filter(x=>state.completed.has(x)).length*15;const lab=state.completed.has(4)?20:state.guidedDone.size/guided.length*20;const examP=state.completed.has(5)?15:0;const ladder=state.ladderDone.size/ladderItems.length*20;const pct=Math.min(100,Math.round(base+lab+examP+ladder));
  $('#progressLabel').textContent=`${pct}% complete`;$('#headerProgress').style.width=`${pct}%`;$('#pathScore').textContent=`${pct}%`;$$('.section-done').forEach(b=>b.classList.toggle('done',state.completed.has(Number(b.dataset.complete))));
}
function updateResults(){
  $('#guidedScore').textContent=`${state.guidedFirst} / ${guided.length}`;$('#examScore').textContent=state.examScore===null?'— / 10':`${state.examScore} / 10`;const counts={...state.guidedMistakes};if(state.examDone)state.examAnswers.forEach((r,i)=>{if(r&&!r.ok){const f=exam[i].focus;counts[f]=(counts[f]||0)+1;}});const ranked=Object.entries(counts).sort((a,b)=>b[1]-a[1]);
  if(!ranked.length){$('#priorityBox').innerHTML=`<b>Revision priorities</b><p>${state.guidedDone.size||state.examDone?'Strong balance so far. Keep practising accents, numbers and two-listen discipline.':'Complete activities to generate personalised priorities.'}</p>`;return;}
  $('#priorityBox').innerHTML=`<b>Revision priorities</b><p>Focus first on: ${ranked.slice(0,5).map(([k,v])=>`${esc(k)} (${v} ${v===1?'error':'errors'})`).join(' · ')}.</p>`;
}
function toggleComplete(n){state.completed.add(n);persist();updateProgress();}
function download(filename,text,type='text/plain'){const b=new Blob([text],{type});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=filename;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},100);}
function makeReport(){const priorities=Object.entries(state.guidedMistakes).sort((a,b)=>b[1]-a[1]).slice(0,5).map(x=>x[0]);return `CLOE SUCCESS PATH · LESSON 05 · LISTENING COMPREHENSION\n\nTraining resource — not an official CLOE score.\n\nGuided first-attempt score: ${state.guidedFirst}/${guided.length}\nTimed mini-test: ${state.examScore===null?'Not completed':state.examScore+'/10'}\nGuided activities completed: ${state.guidedDone.size}/${guided.length}\nAdaptive ladder completed: ${state.ladderDone.size}/${ladderItems.length}\n\nRevision priorities: ${priorities.length?priorities.join(', '):'Continue two-listen practice with varied professional audio.'}\n\nCore method: L.I.S.T.E.N. = Look · Identify · Sense · Target · Evidence · Nail it.\n`;}
function resetAll(){if(!confirm('Reset all Lesson 5 progress?'))return;stopSpeech();try{localStorage.removeItem(STORAGE);}catch(e){}location.reload();}

function wire(){
  $$('[data-scroll]').forEach(b=>b.addEventListener('click',()=>document.querySelector(b.dataset.scroll)?.scrollIntoView({behavior:'smooth'})));$$('.section-done').forEach(b=>b.addEventListener('click',()=>toggleComplete(Number(b.dataset.complete))));$('#toggleFrench').addEventListener('click',()=>setFrench(!state.fr));$('#guidedMode').addEventListener('click',()=>setMode(false));$('#soloMode').addEventListener('click',()=>setMode(true));
  ['levelFilter','typeFilter','audioSearch'].forEach(id=>$('#'+id).addEventListener(id==='audioSearch'?'input':'change',()=>renderAudioLibrary()));$('#accentFilter').addEventListener('change',e=>{state.accent=e.target.value;persist();renderGuided();renderLadder();renderAudioLibrary();});
  $('#openCoach').addEventListener('click',()=>$('#coachDialog').showModal());$('#startExam').addEventListener('click',startExam);$('#downloadReport').addEventListener('click',()=>download('CLOE_Lesson_05_Listening_Report.txt',makeReport()));$('#exportProgress').addEventListener('click',()=>download('CLOE_Lesson_05_Listening_Progress.json',JSON.stringify({lesson:5,title:'Listening Comprehension',guidedFirst:state.guidedFirst,guidedCompleted:state.guidedDone.size,examScore:state.examScore,completedSections:[...state.completed],revision:state.guidedMistakes,accent:state.accent},null,2),'application/json'));$('#resetAll').addEventListener('click',resetAll);window.addEventListener('beforeunload',stopSpeech);
}
function tickClock(){const s=Math.floor((Date.now()-startTime)/1000);$('#lessonClock').textContent=formatTime(s);}

restore();renderListeningMap();populateFilters();renderAudioLibrary();renderGuided();renderLadder();setupExamDots();wire();updateProgress();updateResults();setFrench(state.fr);setMode(state.solo);tickClock();setInterval(tickClock,1000);
